    @Override public boolean onKeyDown(int key,KeyEvent e){
      if(menuMode!=0){if(key==KeyEvent.KEYCODE_DPAD_DOWN){stepMenu(1);return true;}if(key==KeyEvent.KEYCODE_DPAD_UP){stepMenu(-1);return true;}if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT){if(e.getRepeatCount()==0&&menuValues())activateMenu(key==KeyEvent.KEYCODE_DPAD_LEFT?-1:1);return true;}if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){if(e.getRepeatCount()==0)activateMenu(0);return true;}if(key==KeyEvent.KEYCODE_MENU){closeMenu();return true;}return super.onKeyDown(key,e);}
      if(merchantPage){if(gameOpen){gameKey(key,e);return true;}if(refreshAge(SystemClock.uptimeMillis())>=0)return true;if(!MerchantMotion.ready(merchantAge())){if(key==23||key==66){merchantStarted=SystemClock.uptimeMillis()-MerchantMotion.READY;invalidate();}return true;}if(key==19){merchantTools=0;invalidate();return true;}if(key==20){merchantTools=-1;invalidate();return true;}if(key==21||key==22){if(merchantTools>=0)merchantTools=Math.floorMod(merchantTools+(key==21?-1:1),3);else merchantSelected=MerchantMotion.nextCard(merchantSelected,key==21?-1:1);invalidate();return true;}if((key==23||key==66)&&e.getRepeatCount()==0){if(merchantTools==0)refreshCards();else if(merchantTools==1)openGame();else if(merchantTools==2)openMenu(13);else merchantAction();}return true;}
      if(selected==6&&(key==21||key==22)){cycleHero(key==21?-1:1);return true;}
      if(key==KeyEvent.KEYCODE_DPAD_RIGHT){if(selected==5&&visualVersion>=12&&e.getRepeatCount()==0)openMerchant();else move(selected==6?0:(selected+1)%6);return true;}
      if(key==KeyEvent.KEYCODE_DPAD_LEFT){move(selected==6?5:(selected+5)%6);return true;}
      if(key==KeyEvent.KEYCODE_DPAD_DOWN){focusHeroes();return true;}
      if(key==KeyEvent.KEYCODE_DPAD_UP){if(selected==6){selected=heroReturn;stopJump();invalidate();}return true;}
      if(key==KeyEvent.KEYCODE_MENU){allApps();return true;}
      if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){if(e.getRepeatCount()==0){if(selected==6)applyHero();else if(selected==5)openMenu(1);else launch(packages[selected]);}return true;}
      return super.onKeyDown(key,e);
    }
